points.code:
forever {
  next costume
  wait (0.1) secs
}

broadcast [start_race]
---
when I receive [start_race]
repeat (10) {
  move (10) steps
}

when [space] key pressed
repeat (10) {
  change y by (10)
}
repeat (10) {
  change y by (-10)
}

define Jump {
  change y by (20)
  wait (0.1) secs
  change y by (-20)
}

define DrawSquare (size) {
  repeat (4) {
    move (size) steps
    turn clockwise (90) degrees
  }
}

set [gravity] to (-1)
forever {
  change [y_velocity] by (gravity)
  change y by (y_velocity)
}

when green flag clicked
repeat (3) {
  create clone of [Ball]
}

forever {
  go to [mouse-pointer]
}
